const cleanHeaderLogoText = (value?: string | null) => {
  const raw = String(value || "").trim();
  if (!raw || raw.startsWith("data:image/") || /^https?:\/\//i.test(raw)) return raw;
  const withoutBrokenEmoji = raw
    .replace(/[^\x20-\x7E]+/g, " ")
    .replace(/\b(?:a|ae|oe|yen|tm|copy|reg)\b/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
  return withoutBrokenEmoji.toUpperCase().includes("SK LOVE") ? "SK LOVE" : withoutBrokenEmoji || "SK LOVE";
};

