const detectSliderMediaType = (url?: string): "image" | "video" | "gif" => {
  const value = String(url || "").toLowerCase();
  if (value.startsWith("data:video/") || value.includes(".mp4")) return "video";
  if (value.startsWith("data:image/gif") || value.includes(".gif")) return "gif";
  return "image";
};

let lastGeneratedId = Date.now();
const generateUniqueNumberId = (): number => {
  const now = Date.now();
  if (now <= lastGeneratedId) {
    lastGeneratedId += 1;
  } else {
    lastGeneratedId = now;
  }
  return lastGeneratedId;
};

// Real Webcam Stream preview component
interface WebcamStreamVideoProps {
  className?: string;
  isCameraOff: boolean;
  filterClass?: string;
}

const WebcamStreamVideo: React.FC<WebcamStreamVideoProps> = ({
  className = "",
  isCameraOff,
  filterClass = "",
}) => {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);


  // ---- ইফেক্ট: useEffect — let activeStream: MediaStream | null = null; ----
  useEffect(() => {
    let activeStream: MediaStream | null = null;

    if (!isCameraOff) {
      navigator.mediaDevices
        .getUserMedia({ video: { width: 480, height: 360 }, audio: false })
        .then((s) => {
          activeStream = s;
          setStream(s);
          setError(null);
          if (videoRef.current) {
            videoRef.current.srcObject = s;
          }
        })
        .catch((err) => {
          console.error("Camera access error:", err);
          setError(err.name === "NotAllowedError" ? "Permission Refused" : "Camera not found");
        });
    } else {
      if (stream) {
        stream.getTracks().forEach((track) => track.stop());
        setStream(null);
      }
    }

    return () => {
      if (activeStream) {
        activeStream.getTracks().forEach((track) => track.stop());
      }
    };
  }, [isCameraOff]);

  if (isCameraOff) {
    return (
      <div className="w-full h-full bg-slate-950 flex flex-col items-center justify-center p-2 text-center">
        <span className="text-xl select-none">🙈</span>
        <p className="text-[8px] text-slate-500 font-extrabold uppercase mt-1">CAMERA OFF</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="w-full h-full bg-slate-950 flex flex-col items-center justify-center p-2 text-center text-[8.5px] text-rose-400 font-bold border border-rose-950/20">
        <span>⚠️ {error}</span>
        <p className="text-[7.5px] mt-0.5 text-slate-500 font-medium">
          Please check your camera device connection
        </p>
      </div>
    );
  }

  return (
    <video
      ref={videoRef}
      autoPlay
      playsInline
      muted
      className={`${className} ${filterClass} object-cover w-full h-full`}
    />
  );
};

