  // ========================================================================
  const [cropTargetType, setCropTargetType] = useState<"avatar" | "cover" | null>(null);
  const [uploadedImageSrc, setUploadedImageSrc] = useState<string | null>(null);
  const [cropScale, setCropScale] = useState<number>(1.0);
  const [cropRotate, setCropRotate] = useState<number>(0);
  const [cropOffset, setCropOffset] = useState<{ x: number; y: number }>({ x: 0, y: 0 });


  // ---- হ্যান্ডলার: ফাইল আপলোড (handleImageUploadClick) ----
  const handleImageUploadClick = (
    e: React.ChangeEvent<HTMLInputElement>,
    type: "avatar" | "cover",
  ) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          setUploadedImageSrc(event.target.result as string);
          setCropTargetType(type);
          setCropScale(1.0);
          setCropRotate(0);
        }
      };
      reader.readAsDataURL(file);
    }
  };

