  const [liveProfileRole, setLiveProfileRole] = useState<string | null>(null);
  const [liveProfileRoleLoading, setLiveProfileRoleLoading] = useState(false);
  useEffect(() => {
    const uid = selectedProfileUser?.id;
    if (!uid) {
      setLiveProfileRole(null);
      return;
    }
    let cancelled = false;
    setLiveProfileRoleLoading(true);
    (async () => {
      try {
        // Always fetch the latest user row from the Laravel DB (users table).
        // Backend endpoint: GET /api/users/{id} → { user: { role, ... } }
        const resp: any = await api.get(`/api/users/${uid}`, { auth: true });
        if (cancelled) return;
        const fresh = resp?.user ?? resp?.data ?? resp;
        const r = String(fresh?.role ?? fresh?.user_role ?? "user").toLowerCase();
        setLiveProfileRole(r);



      } catch (e) {
        if (!cancelled) setLiveProfileRole(null);
        // eslint-disable-next-line no-console
        console.warn("[LIVE ROLE] fetch failed", e);
      } finally {
        if (!cancelled) setLiveProfileRoleLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [selectedProfileUser?.id]);

