  const upsertLiveRemoteVideoTile = (
    uidValue: unknown,
    patch: Partial<{ track: any | null; name: string; avatar: string | null }> = {},
  ) => {
    const uid = String(uidValue ?? "").trim();
    if (!uid) return;
    if (patch.track) {
      liveRemoteVideoTracksRef.current[uid] = patch.track;
    } else if (Object.prototype.hasOwnProperty.call(patch, "track") && !patch.track) {
      delete liveRemoteVideoTracksRef.current[uid];
    }
    setLiveRemoteVideos((current) => {
      const existing = current.find((item) => String(item.uid) === uid);
      const nextItem = {
        uid,
        track: existing?.track ?? null,
        name: existing?.name,
        avatar: existing?.avatar ?? null,
        ...patch,
      };
      if (
        existing &&
        existing.track === nextItem.track &&
        existing.name === nextItem.name &&
        existing.avatar === nextItem.avatar
      ) {
        return current;
      }
      return [...current.filter((item) => String(item.uid) !== uid), nextItem];
    });
  };

  const playLiveRemoteVideoTrack = (uidValue: unknown, trackValue?: any) => {
    const uid = String(uidValue ?? "").trim();
    if (!uid) return;
    const container = liveRemoteVideoRefs.current[uid];
    const track = trackValue || liveRemoteVideoTracksRef.current[uid];
    if (!container || !track) return;
    try {
      container.innerHTML = "";
      track.play(container);
    } catch {
      // Agora may reject until the DOM tile is mounted; the effect/interval retries.
    }
  };

