  // ---- Store: owned avatar frames { id -> expiryTimestamp(ms) } + currently equipped ----
  const [ownedAvatarFrames, setOwnedAvatarFrames] = useState<Record<string, number>>(() => {
    try {
      const raw = typeof window !== "undefined" ? window.localStorage.getItem("sk_owned_avatar_frames") : null;
      if (!raw) return {};
      const parsed = JSON.parse(raw) as Record<string, number>;
      const now = Date.now();
      const cleaned: Record<string, number> = {};
      Object.entries(parsed).forEach(([k, v]) => {
        const exp = Number(v);
        if (Number.isFinite(exp) && exp > now) cleaned[k] = exp;
      });
      return cleaned;
    } catch {
      return {};
    }
  });
  const [equippedAvatarFrame, setEquippedAvatarFrame] = useState<string | null>(() => {
    try {
      return typeof window !== "undefined" ? window.localStorage.getItem("sk_equipped_avatar_frame") : null;
    } catch {
      return null;
    }
  });
  useEffect(() => {
    try {
      window.localStorage.setItem("sk_owned_avatar_frames", JSON.stringify(ownedAvatarFrames));
    } catch {}
  }, [ownedAvatarFrames]);
  useEffect(() => {
    try {
      if (equippedAvatarFrame) window.localStorage.setItem("sk_equipped_avatar_frame", equippedAvatarFrame);
      else window.localStorage.removeItem("sk_equipped_avatar_frame");
    } catch {}
  }, [equippedAvatarFrame]);
  // Auto-remove expired frames every 60s
  useEffect(() => {
    const sweep = () => {
      const now = Date.now();
      setOwnedAvatarFrames((prev) => {
        const next: Record<string, number> = {};
        let changed = false;
        Object.entries(prev).forEach(([k, v]) => {
          if (v > now) next[k] = v;
          else changed = true;
        });
        return changed ? next : prev;
      });
    };
    sweep();
    const t = window.setInterval(sweep, 60_000);
    return () => window.clearInterval(t);
  }, []);
  // Un-equip if the equipped one has expired / not owned
  useEffect(() => {
    if (equippedAvatarFrame && !ownedAvatarFrames[equippedAvatarFrame]) {
      setEquippedAvatarFrame(null);
    }
  }, [equippedAvatarFrame, ownedAvatarFrames]);
  const activeAvatarFrameImg = equippedAvatarFrame
