  // Auto-award ride effects based on Recharge Gift Offers table
  const checkAndAutoAwardRechargeOffer = (rechargeAmount: number) => {
    if (!rechargeAmount || rechargeAmount <= 0) return;

    const matchedOffers = RIDES_CATALOG.filter((r) => rechargeAmount >= (r.rechargeRequirement || r.numericPrice));
    if (matchedOffers.length === 0) return;

    const now = Date.now();
    let highestOffer = matchedOffers[0];

    matchedOffers.forEach((offer) => {
      if ((offer.rechargeRequirement || offer.numericPrice) > (highestOffer.rechargeRequirement || highestOffer.numericPrice)) {
        highestOffer = offer;
      }
    });

    setOwnedRides((prev) => {
      const next = { ...prev };
      matchedOffers.forEach((offer) => {
        let durationDays = 7;
        if (offer.rechargeRequirement <= 300000) durationDays = 3;
        else if (offer.rechargeRequirement >= 7000000) durationDays = 30;
        else if (offer.rechargeRequirement === 5000000) durationDays = 15;

        const durationMs = durationDays * 24 * 60 * 60 * 1000;
        const currentExp = next[offer.id] || 0;
        next[offer.id] = Math.max(currentExp, now + durationMs);
      });
      return next;
    });

    setEquippedRide(highestOffer.id);
    triggerSystemAnnouncement(
      `🎉 Recharge Offer Unlocked: ${highestOffer.name} (${highestOffer.emoji})!`
    );
  };

  // Audio synthesis for Royal Entry Effect (Distinct per ride)
  const playEntryEffectSound = (rideId?: string) => {
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioCtx) return;
      const ctx = new AudioCtx();

      const effectId = rideId || equippedRide || "rides-jaguar";

      switch (effectId) {
        case "rides-jaguar": {
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = "sawtooth";
          osc.frequency.setValueAtTime(90, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(320, ctx.currentTime + 1.2);
          osc.frequency.linearRampToValueAtTime(140, ctx.currentTime + 3.0);
          gain.gain.setValueAtTime(0.04, ctx.currentTime);
          gain.gain.linearRampToValueAtTime(0.09, ctx.currentTime + 1.0);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 3.2);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start(ctx.currentTime);
          osc.stop(ctx.currentTime + 3.3);

          [880, 1108].forEach((freq) => {
            const hOsc = ctx.createOscillator();
            const hGain = ctx.createGain();
            hOsc.type = "sine";
            hOsc.frequency.setValueAtTime(freq, ctx.currentTime + 0.8);
            hGain.gain.setValueAtTime(0.05, ctx.currentTime + 0.8);
            hGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1.6);
            hOsc.connect(hGain);
            hGain.connect(ctx.destination);
            hOsc.start(ctx.currentTime + 0.8);
            hOsc.stop(ctx.currentTime + 1.7);
          });
          break;
        }

        case "rides-tarzen": {
          [55, 110].forEach((freq, idx) => {
            const drum = ctx.createOscillator();
            const dGain = ctx.createGain();
            drum.type = "sine";
            drum.frequency.setValueAtTime(freq, ctx.currentTime + idx * 0.25);
            drum.frequency.exponentialRampToValueAtTime(30, ctx.currentTime + idx * 0.25 + 0.3);
            dGain.gain.setValueAtTime(0.12, ctx.currentTime + idx * 0.25);
            dGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.25 + 0.35);
            drum.connect(dGain);
            dGain.connect(ctx.destination);
            drum.start(ctx.currentTime + idx * 0.25);
            drum.stop(ctx.currentTime + idx * 0.25 + 0.4);
          });

          [220, 277, 330, 440, 554, 659].forEach((freq, idx) => {
            const hOsc = ctx.createOscillator();
            const hGain = ctx.createGain();
            hOsc.type = "triangle";
            hOsc.frequency.setValueAtTime(freq, ctx.currentTime + 0.4 + idx * 0.15);
            hGain.gain.setValueAtTime(0.06, ctx.currentTime + 0.4 + idx * 0.15);
            hGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4 + idx * 0.15 + 0.5);
            hOsc.connect(hGain);
            hGain.connect(ctx.destination);
            hOsc.start(ctx.currentTime + 0.4 + idx * 0.15);
            hOsc.stop(ctx.currentTime + 0.4 + idx * 0.15 + 0.55);
          });
          break;
        }

        case "rides-vip-ride": {
          const engine = ctx.createOscillator();
          const eGain = ctx.createGain();
          engine.type = "triangle";
          engine.frequency.setValueAtTime(75, ctx.currentTime);
          engine.frequency.linearRampToValueAtTime(180, ctx.currentTime + 1.5);
          eGain.gain.setValueAtTime(0.05, ctx.currentTime);
          eGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 2.8);
          engine.connect(eGain);
          eGain.connect(ctx.destination);
          engine.start(ctx.currentTime);
          engine.stop(ctx.currentTime + 3.0);

          [523.25, 659.25, 783.99, 1046.50].forEach((freq, idx) => {
            const chime = ctx.createOscillator();
            const cGain = ctx.createGain();
            chime.type = "sine";
            chime.frequency.setValueAtTime(freq, ctx.currentTime + 0.3 + idx * 0.15);
            cGain.gain.setValueAtTime(0.07, ctx.currentTime + 0.3 + idx * 0.15);
            cGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3 + idx * 0.15 + 0.8);
            chime.connect(cGain);
            cGain.connect(ctx.destination);
            chime.start(ctx.currentTime + 0.3 + idx * 0.15);
            chime.stop(ctx.currentTime + 0.3 + idx * 0.15 + 0.85);
          });
          break;
        }

        case "rides-richman": {
          [1200, 1400, 1600, 1800, 2000, 2200, 2400].forEach((freq, idx) => {
            const coin = ctx.createOscillator();
            const cGain = ctx.createGain();
            coin.type = "sine";
            coin.frequency.setValueAtTime(freq, ctx.currentTime + idx * 0.08);
            cGain.gain.setValueAtTime(0.04, ctx.currentTime + idx * 0.08);
            cGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.08 + 0.25);
            coin.connect(cGain);
            cGain.connect(ctx.destination);
            coin.start(ctx.currentTime + idx * 0.08);
            coin.stop(ctx.currentTime + idx * 0.08 + 0.28);
          });

          [261.63, 329.63, 392.00, 493.88, 523.25].forEach((freq) => {
            const orch = ctx.createOscillator();
            const oGain = ctx.createGain();
            orch.type = "triangle";
            orch.frequency.setValueAtTime(freq, ctx.currentTime + 0.6);
            oGain.gain.setValueAtTime(0.05, ctx.currentTime + 0.6);
            oGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 2.5);
            orch.connect(oGain);
            oGain.connect(ctx.destination);
            orch.start(ctx.currentTime + 0.6);
            orch.stop(ctx.currentTime + 2.6);
          });
          break;
        }

        case "rides-lion2": {
          const roar = ctx.createOscillator();
          const rGain = ctx.createGain();
          roar.type = "sawtooth";
          roar.frequency.setValueAtTime(45, ctx.currentTime);
          roar.frequency.linearRampToValueAtTime(95, ctx.currentTime + 1.0);
          roar.frequency.exponentialRampToValueAtTime(35, ctx.currentTime + 2.5);
          rGain.gain.setValueAtTime(0.08, ctx.currentTime);
          rGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 2.6);
          roar.connect(rGain);
          rGain.connect(ctx.destination);
          roar.start(ctx.currentTime);
          roar.stop(ctx.currentTime + 2.7);

          [349.23, 440.00, 523.25, 698.46].forEach((freq, idx) => {
            const t = ctx.createOscillator();
            const tg = ctx.createGain();
            t.type = "sawtooth";
            t.frequency.setValueAtTime(freq, ctx.currentTime + 0.5 + idx * 0.2);
            tg.gain.setValueAtTime(0.04, ctx.currentTime + 0.5 + idx * 0.2);
            tg.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5 + idx * 0.2 + 0.7);
            t.connect(tg);
            tg.connect(ctx.destination);
            t.start(ctx.currentTime + 0.5 + idx * 0.2);
            t.stop(ctx.currentTime + 0.5 + idx * 0.2 + 0.75);
          });
          break;
        }

        case "rides-dragon2": {
          const dragon = ctx.createOscillator();
          const dGain = ctx.createGain();
          dragon.type = "sawtooth";
          dragon.frequency.setValueAtTime(180, ctx.currentTime);
          dragon.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 2.2);
          dGain.gain.setValueAtTime(0.09, ctx.currentTime);
          dGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 2.4);
          dragon.connect(dGain);
          dGain.connect(ctx.destination);
          dragon.start(ctx.currentTime);
          dragon.stop(ctx.currentTime + 2.5);
          break;
        }

        case "rides-neoncar": {
          [300, 450, 600, 900, 1200, 1800, 2400].forEach((freq, idx) => {
            const synth = ctx.createOscillator();
            const sGain = ctx.createGain();
            synth.type = "square";
            synth.frequency.setValueAtTime(freq, ctx.currentTime + idx * 0.12);
            sGain.gain.setValueAtTime(0.04, ctx.currentTime + idx * 0.12);
            sGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.12 + 0.3);
            synth.connect(sGain);
            sGain.connect(ctx.destination);
            synth.start(ctx.currentTime + idx * 0.12);
            synth.stop(ctx.currentTime + idx * 0.12 + 0.35);
          });
          break;
        }

        case "rides-tiger": {
          const tiger = ctx.createOscillator();
          const tGain = ctx.createGain();
          tiger.type = "sawtooth";
          tiger.frequency.setValueAtTime(60, ctx.currentTime);
          tiger.frequency.linearRampToValueAtTime(120, ctx.currentTime + 0.6);
          tiger.frequency.linearRampToValueAtTime(50, ctx.currentTime + 1.8);
          tGain.gain.setValueAtTime(0.08, ctx.currentTime);
          tGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 2.0);
          tiger.connect(tGain);
          tGain.connect(ctx.destination);
          tiger.start(ctx.currentTime);
          tiger.stop(ctx.currentTime + 2.1);
          break;
        }

        case "rides-knife": {
          const knife = ctx.createOscillator();
          const kGain = ctx.createGain();
          knife.type = "sine";
          knife.frequency.setValueAtTime(2800, ctx.currentTime);
          knife.frequency.exponentialRampToValueAtTime(600, ctx.currentTime + 0.4);
          kGain.gain.setValueAtTime(0.09, ctx.currentTime);
          kGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);
          knife.connect(kGain);
          kGain.connect(ctx.destination);
          knife.start(ctx.currentTime);
          knife.stop(ctx.currentTime + 0.55);

          [1800, 2200, 2600].forEach((freq) => {
            const ring = ctx.createOscillator();
            const rGain = ctx.createGain();
            ring.type = "sine";
            ring.frequency.setValueAtTime(freq, ctx.currentTime + 0.2);
            rGain.gain.setValueAtTime(0.05, ctx.currentTime + 0.2);
            rGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1.5);
            ring.connect(rGain);
            rGain.connect(ctx.destination);
            ring.start(ctx.currentTime + 0.2);
            ring.stop(ctx.currentTime + 1.6);
          });
          break;
        }

        case "rides-phnix": {
          const flame = ctx.createOscillator();
          const fGain = ctx.createGain();
          flame.type = "triangle";
          flame.frequency.setValueAtTime(250, ctx.currentTime);
          flame.frequency.exponentialRampToValueAtTime(1600, ctx.currentTime + 1.8);
          fGain.gain.setValueAtTime(0.06, ctx.currentTime);
          fGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 2.2);
          flame.connect(fGain);
          fGain.connect(ctx.destination);
          flame.start(ctx.currentTime);
          flame.stop(ctx.currentTime + 2.3);

          [523.25, 659.25, 783.99, 1046.50, 1318.51, 1567.98].forEach((freq, idx) => {
            const harp = ctx.createOscillator();
            const hGain = ctx.createGain();
            harp.type = "sine";
            harp.frequency.setValueAtTime(freq, ctx.currentTime + 0.5 + idx * 0.1);
            hGain.gain.setValueAtTime(0.05, ctx.currentTime + 0.5 + idx * 0.1);
            hGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5 + idx * 0.1 + 0.8);
            harp.connect(hGain);
            hGain.connect(ctx.destination);
            harp.start(ctx.currentTime + 0.5 + idx * 0.1);
            harp.stop(ctx.currentTime + 0.5 + idx * 0.1 + 0.85);
          });
          break;
        }

        case "rides-vip1":
        case "rides-vip2":
        case "rides-vip3": {
          const multiplier = effectId === "rides-vip3" ? 1.5 : effectId === "rides-vip2" ? 1.2 : 1.0;
          const baseFreqs = [261.63, 329.63, 392.00, 523.25, 659.25, 783.99, 1046.50];

          baseFreqs.forEach((freq, idx) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = "sine";
            osc.frequency.setValueAtTime(freq * multiplier, ctx.currentTime + idx * 0.15);

            gain.gain.setValueAtTime(0.02, ctx.currentTime + idx * 0.15);
            gain.gain.exponentialRampToValueAtTime(0.08 * multiplier, ctx.currentTime + idx * 0.15 + 0.05);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.15 + 0.8);

            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start(ctx.currentTime + idx * 0.15);
            osc.stop(ctx.currentTime + idx * 0.15 + 0.85);
          });
          break;
        }

        default: {
          const notes = [392.00, 523.25, 659.25, 783.99, 1046.50];
          notes.forEach((freq, index) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = "sine";
            osc.frequency.setValueAtTime(freq, ctx.currentTime + index * 0.18);
            gain.gain.setValueAtTime(0.01, ctx.currentTime + index * 0.18);
            gain.gain.exponentialRampToValueAtTime(0.15, ctx.currentTime + index * 0.18 + 0.05);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + index * 0.18 + 0.5);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start(ctx.currentTime + index * 0.18);
            osc.stop(ctx.currentTime + index * 0.18 + 0.55);
          });
          break;
        }
      }
    } catch {
      /* Browser autoplay policy check */
    }
  };

