// new: party gift popup
const [isPartyGiftPopupOpen, setIsPartyGiftPopupOpen] = useState<boolean>(false);
// ...existing code...

  // Premium Features for Party Room
  const [maxGuestSeats, setMaxGuestSeats] = useState<number>(8);
  // FIX (guest seat setting): Track whether the host has explicitly chosen a
  // seat count locally. Once set, the polling response from applyPartyRoomState
  // must not overwrite the user's choice (previously a stale server value like
  // 10 was clobbering a fresh local selection of 5/8 etc.).
  const maxGuestSeatsUserSetRef = useRef<boolean>(false);
  // FIX (seat lock): host can lock empty seats so no one can sit on them.
  // Stored as a Set<number> of seat INDEXES (0 = crown host seat, 1..N = other seats).
  // Synced with backend via the same settings endpoint used for maxGuestSeats.
  const [lockedSeats, setLockedSeats] = useState<Set<number>>(new Set());
  const lockedSeatsUserSetRef = useRef<boolean>(false);
  const persistLockedSeats = async (next: Set<number>) => {
    const roomId = activePartyRoom?.id;
    if (!roomId) return;
    const arr = Array.from(next).sort((a, b) => a - b);
    const payload = { lockedSeats: arr };
    // Fire-and-forget; backend may ignore unknown fields until it adds support.
    try { await api.post(`/api/party-rooms/${roomId}/settings`, payload); } catch { /* ignore */ }
  };
  const toggleSeatLock = (seatIndex: number) => {
    // Only host can lock/unlock. Cannot lock an occupied seat.
    const uid = getCurrentUserId();
    const iAmHost =
      Boolean(activePartyRoom?.hostId) &&
      Boolean(uid) &&
      Number(activePartyRoom.hostId) === Number(uid);
    if (!iAmHost) return;
    const seat = partySeats[seatIndex];
    if (seat?.occupant) {
      triggerSystemAnnouncement("Cannot lock an occupied seat.");
      return;
    }
    setLockedSeats((prev) => {
      const next = new Set(prev);
      if (next.has(seatIndex)) next.delete(seatIndex);
      else next.add(seatIndex);
      lockedSeatsUserSetRef.current = true;
      void persistLockedSeats(next);
      return next;
    });
  };
