  // Batch 2: Load room-specific seat coin totals when joining a room (or reset when leaving).
  // Also clear chat comments + emoji overlays so a previous session's messages
  // never linger into a new room / new session.
  useEffect(() => {
    activePartyRoomIdRef.current = activePartyRoom?.id ?? null;
    if (isPartyRoomOpen && activePartyRoom?.id) {
      const storedCoins = getStoredPartyRoomCoins(activePartyRoom.id);
      setPartySeatSessionCoins(storedCoins);

      const storedGifters = getStoredPartyRoomGifters(activePartyRoom.id);
      const gifterMap = new Map<string, { name: string; avatar: string; totalSpent: number }>();
      storedGifters.forEach((g) => {
        if (g && g.name) gifterMap.set(g.name.trim().toLowerCase(), g);
      });
      partyGifterTotalsRef.current = gifterMap;

      let leader: { name: string; avatar: string; totalSpent: number } | null = null;
      gifterMap.forEach((entry) => {
        if (!leader || entry.totalSpent > leader.totalSpent) leader = entry;
      });
      setTopGifter(leader);
      setPartyGifterTick((t) => t + 1);
    } else {
      setPartySeatSessionCoins({});
    }
    setPartyChatMessages([]);
    setPartyChatReplyTo(null);
    setSeatEmojiOverlay({});
  }, [activePartyRoom?.id, isPartyRoomOpen]);
  // Party room in-room chat (host + guests can comment & reply)
  type PartyChatMsg = {
    id: number;
    name: string;
    text: string;
    replyToId?: number;
    replyToName?: string;
  };
  const [partyChatMessages, setPartyChatMessages] = useState<PartyChatMsg[]>([]);
  const [partyChatDraft, setPartyChatDraft] = useState<string>("");
  const [partyChatReplyTo, setPartyChatReplyTo] = useState<PartyChatMsg | null>(null);
  // FIX: default 2 comments visible; toggle to show 5-at-a-time with hidden scroll.
  const [isPartyChatExpanded, setIsPartyChatExpanded] = useState<boolean>(false);
  const [isPartyCommentsOpen, setIsPartyCommentsOpen] = useState<boolean>(true);
  // FIX (UI parity): party-room comment input now uses the same popup-triggered
  // pencil button pattern as the video-streaming footer. Logic unchanged.
  const [isPartyCommentPopupOpen, setIsPartyCommentPopupOpen] = useState<boolean>(false);
  const sendPartyChat = () => {
    const body = partyChatDraft.trim();
    if (!body) return;
    // Optimistic message uses a NEGATIVE id so applyPartyRoomState can tell it
    // apart from server rows (positive DB ids) and drop it once the poll
    // returns the confirmed copy (matched by name+text).
    const msg: PartyChatMsg = {
      id: -(Date.now() + Math.floor(Math.random() * 1000)),
      name: registerName || "You",
      text: body,
      replyToId: partyChatReplyTo?.id,
      replyToName: partyChatReplyTo?.name,
    };
    setPartyChatMessages((prev) => [...prev.slice(-49), msg]);
    const replyToName = partyChatReplyTo?.name;
    setPartyChatDraft("");
    setPartyChatReplyTo(null);
    // Broadcast so the host and every other guest sees the comment via poll.
    if (activePartyRoom?.id) {
      api
        .post(`/api/party-rooms/${activePartyRoom.id}/chat`, {
          text: body,
          replyToName: replyToName || undefined,
        })
        .then((res: any) => {
          const data = res?.data ?? res;
          if (data) applyPartyRoomState(data);
        })
        .catch(() => {
          /* endpoint may not be deployed yet — local message still shows */
        });
    }
  };
