    partySeats.forEach((s) => {
      if (!s?.occupant) return;
      const key = String(s.userId ?? s.occupant);
      seen.add(key);
      const cur = sess.seatUsers.get(key);
      if (!cur) {
        sess.seatUsers.set(key, { name: s.occupant, totalMs: 0, lastEnterTs: now });
      } else if (!cur.lastEnterTs) {
        cur.lastEnterTs = now;
      }
    });
