        // host as a guest and evict them.
        const localRoomId = Number(activePartyRoom?.id ?? 0);
        const isLocallyHostedRoom = Boolean(
          localRoomId && locallyHostedPartyRoomIdsRef.current.has(localRoomId),
        );
        const localHostId = Number(activePartyRoom?.hostId ?? 0);
        const serverHostId = Number(data?.data?.hostId ?? 0);
        const effectiveHostId = localHostId || serverHostId;
        const isHost =
          isLocallyHostedRoom ||
          (Boolean(effectiveHostId) && Number(currentUserId) === effectiveHostId);
